from scipy import ndimage

def solve(gin):
    g=np.array(gin); H,W=g.shape
    seen=np.zeros_like(g,bool); out=g.copy()
    dirs=[(1,0),(-1,0),(0,1),(0,-1)]
    for i in range(H):
        for j in range(W):
            v=g[i,j]
            if v in (0,8) or seen[i,j]: continue
            # BFS component of this color
            stack=[(i,j)]; comp=[]
            while stack:
                r,c=stack.pop()
                if 0<=r<H and 0<=c<W and g[r,c]==v and not seen[r,c]:
                    seen[r,c]=True; comp.append((r,c)); stack+= [(r+dr,c+dc) for dr,dc in dirs]
            if v==0: continue
            rs=[r for r,c in comp]; cs=[c for r,c in comp]
            r0,c0=min(rs),min(cs); br,bc=max(rs)-r0+1,max(cs)-c0+1
            stamp=np.zeros((br,bc),bool)
            for r,c in comp: stamp[r-r0,c-c0]=True
            for (r,c) in list(seen)&np.zeros_like(seen): pass
            # flood zeros connected to this shape's cells (4-conn through zeros)
            zstack=list(comp)  # start from shape neighbors? actually from shape cells
            zcomp=set()
            stk=[(r,c) for r,c in comp]
            while stk:
                rr,cc=stk.pop()
                for dr,dc in dirs:
                    nr,nc=rr+dr,cc+dc
                    if 0<=nr<H and 0<=nc<W and g[nr,nc]==0 and (nr,nc) not in zcomp:
                        zcomp.add((nr,nc)); stk.append((nr,nc))
            for (zr,zc) in zcomp:
                si,sj=zr-r0-(zr%br),zc-c0-(zc%bc)
                if 0<=si<br and 0<=sj<bc and stamp[si,sj]:
                    out[zr,zc]=v
    return out.tolist()

