def shape_of(region,grid):
    # nonzero cells adjacent (4-conn) to this region
    adj=set()
    for r,c in region:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<len(grid) and 0<=nc<len(grid[0]) and grid[nr][nc]!=0:
                adj.add((nr,nc))
    # largest connected group among adjacent nonzero cells
    comps_nz=[]; seen_sz=set()
    for cell in adj:
        if cell in seen_sz: continue
        q=deque([cell]); seen_sz.add(cell); comp=[cell]
        while q:
            a,b=q.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nb=(a+dr,b+dc)
                if 0<=nb[0]<len(grid) and 0<=nb[1]<len(grid[0]) and nb in adj and nb not in seen_sz:
                    seen_sz.add(nb); q.append(nb); comp.append(nb)
        comps_nz.append(comp)
    big=max(comps_nz,key=len)
    rs2=[r for r,c in big]; cs2=[c for r,c in big]
    r0=min(rs2); c0=min(cs2)
    br=max(rs2)-r0+1; bc=max(cs2)-c0+1
    stamp=[[int(grid[r][c]) if grid[r][c]!=0 else 0 for c in range(c0,c0+bc)] for r in range(r0,r0+br)]
    return big,(r0,c0,br,bc),stamp

def solve(grid, anchor='region'):
    res=[row[:] for row in grid]
    for region in regions(grid):
        big,anc,stamp=shape_of(region,grid)
        rmin=min(r for r,c in region); cmin=min(c for r,c in region)
        for r,c in region:
            i,j=(r-rmin,c-cmin) if anchor=='region' else (r-anc[0],c-anc[1])
            v=stamp[i%len(stamp)][j%len(stamp[0])]
