                            seen.add((nr,nc)); stack.append((nr,nc)); comp.append((nr,nc))
                comps.append((v,comp))
    regseen=[[False]*w for _ in range(h)]; regs=[]
    def border(reg): return any(r in(0,h-1) or c in(0,w-1) for r,c in reg)
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg and not regseen[r][c]:
                q=deque([(r,c)]); regseen[r][c]=True; comp=[(r,c)]
                while q:
                    a,b=q.popleft()
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=a+dr,b+dc
                        if 0<=nr<h and 0<=nc<w and g[nr][nc]==bg and not regseen[nr][nc]:
                            regseen[nr][nc]=True; q.append((nr,nc)); comp.append((nr,nc))
                regs.append(comp)
    res=[row[:] for row in g]
    for reg in regs:
        if border(reg): continue          # don't tile the outside frame
        adjcells={(r+dr,c+dc) for r,c in reg for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))}
        tc=[i for i,(v,c_) in enumerate(comps) if any(p in adjcells for p in c_)]
        if not tc: continue
        tgt=max(tc,key=lambda i:len(comps[i][1]))
        _,comp=comps[tgt]
